# ============================================================================
# Switchboard identifier validators. All algorithms below were re-implemented
# and executed during research; the test vectors in comments are actual outputs.
# Every function is pure, offline, and must run BEFORE any tool call.
# ============================================================================

DNI_TABLE = "TRWAGMYFPDXBNJZSQVHLCKE"   # 23 letters; omits I, N-tilde, O, U
NIE_PREFIX = {"X": "0", "Y": "1", "Z": "2"}
CIF_CTRL_LETTERS = "JABCDEFGHI"          # J=0, A=1, ... I=9

# --- 1. DNI ---------------------------------------------------------------
def validate_dni(s):
    s = canon(s)                              # strip separators, uppercase
    digits, letter = s[:-1], s[-1]
    if not digits.isdigit() or len(digits) > 8: return FAIL("SHAPE")
    digits = digits.zfill(8)                  # older docs drop leading zeros
    expected = DNI_TABLE[int(digits) % 23]
    if letter != expected: return FAIL("CHECKSUM", segment="control_letter")
    return OK(digits + letter)
# 12345678 -> Z (Ministerio del Interior worked example); 00123456 -> S;
# 65432198 -> G; 00000000 -> T; 99999999 -> R

# --- 2. NIE ---------------------------------------------------------------
def validate_nie(s):
    s = canon(s)
    if len(s) != 9 or s[0] not in NIE_PREFIX: return FAIL("SHAPE", segment="prefix")
    body, letter = NIE_PREFIX[s[0]] + s[1:8], s[8]
    if not s[1:8].isdigit(): return FAIL("SHAPE", segment="digits")
    if letter != DNI_TABLE[int(body) % 23]:
        return FAIL("CHECKSUM", segment="control_letter")
    return OK(s)
# X1234567 -> L; Y0123456 -> Y (prefix == control letter: the drop-a-Y trap);
# Z1234567 -> R; Z0123456 -> C; X0000000 -> T

def route_national_id(s):
    """Caller may say 'DNI' for either. Shape decides, silently."""
    s = canon(s)
    return validate_nie(s) if s[:1] in NIE_PREFIX else validate_dni(s)

# --- 3. CIF / NIF de persona juridica -------------------------------------
ENTITY_LETTERS   = set("ABCDEFGHJNPQRSUVW")   # Orden EHA/451/2008
PERSONAL_LETTERS = set("KLM")                 # RD 1065/2007 - must be accepted
MUST_BE_LETTER   = set("PQRSNW")
MUST_BE_DIGIT    = set("ABEH")

def validate_cif(s):
    s = canon(s)
    if len(s) != 9: return FAIL("SHAPE")
    ent, digits, ctrl = s[0], s[1:8], s[8]
    if ent not in ENTITY_LETTERS | PERSONAL_LETTERS: return FAIL("SHAPE", segment="entity_letter")
    if not digits.isdigit(): return FAIL("SHAPE", segment="digits")
    # class check runs BEFORE the arithmetic: a class violation is usually the
    # caller reading the wrong document, not a mis-heard digit.
    if ent in MUST_BE_LETTER and not ctrl.isalpha(): return FAIL("CTRL_CLASS", ask="which_document")
    if ent in MUST_BE_DIGIT  and not ctrl.isdigit(): return FAIL("CTRL_CLASS", ask="which_document")
    A = sum(int(digits[i]) for i in (1, 3, 5))          # even positions
    B = 0
    for i in (0, 2, 4, 6):                              # odd positions, doubled
        x = int(digits[i]) * 2
        B += x // 10 + x % 10
    D = (10 - (A + B) % 10) % 10
    if ctrl not in (str(D), CIF_CTRL_LETTERS[D]):
        return FAIL("CHECKSUM", segment="digits")
    return OK(s)
# Validated against 11 real NIFs: A28015865 A39000013 A48010615 A78374725
# A15075062 A82018474 A58818501 B84325752 B12345674 Q2826000H G28029643

def cif_entity_letter_for(stated_legal_form):
    return {"sa": "A", "sl": "B", "colectiva": "C", "comanditaria": "D",
            "comunidad_bienes": "E", "cooperativa": "F", "asociacion": "G",
            "comunidad_propietarios": "H", "sociedad_civil": "J",
            "corporacion_local": "P", "organismo_publico": "Q",
            "religiosa": "R", "administracion": "S", "ute": "U", "otros": "V",
            "extranjera": "N", "establecimiento_permanente": "W"}.get(stated_legal_form)

# --- 4. Passports ---------------------------------------------------------
def validate_passport_es(s):
    """No published algorithm -> shape only, PERMISSIVE (8 or 9 chars).
       NEVER report 'valid'; always require an explicit spoken confirmation."""
    s = canon(s)
    if not re.match(r"^[A-Z]{2,3}[0-9]{6}$", s): return FAIL("SHAPE")
    if re.match(r"^[A-Z]{3}[0-9]{6}$", s) and requested_type == "DNI":
        return FAIL("SUPPORT_NUMBER_MIXUP", ask="where_on_the_card")
    return NEEDS_EXPLICIT_CONFIRMATION(s)

def validate_passport_foreign(s):
    s = canon(s)
    if not re.match(r"^[A-Z0-9]{6,9}$", s) or not any(c.isdigit() for c in s):
        return FAIL("SHAPE")
    return NEEDS_EXPLICIT_CONFIRMATION(s)   # issuing country is a separate slot

def icao_check_digit(field):
    """ICAO Doc 9303: weights 7,3,1 repeating; 0-9 -> 0-9, A-Z -> 10-35,
       '<' -> 0; sum mod 10. Only usable when reading the MRZ from a scan."""
    w, total = [7, 3, 1], 0
    for i, c in enumerate(field):
        v = 0 if c == "<" else (int(c) if c.isdigit() else ord(c) - 55)
        total += v * w[i % 3]
    return total % 10
# icao_check_digit("L898902C<") == 3 (ICAO's own specimen)

# --- 5. Phone numbers -----------------------------------------------------
ES_TYPE = [(r"^[89]00", "toll_free"), (r"^90[12]", "shared_cost"),
           (r"^80[367]", "premium"),  (r"^70",    "personal_number"),
           (r"^51",     "uan"),       (r"^(?:6|7[1-48])", "mobile"),
           (r"^[89]",   "fixed_line")]

def validate_phone_es(spoken):
    d = expand_spoken_digits(spoken, lang="es")       # see ASR spec below
    d = re.sub(r"\D", "", d)
    if d.startswith("0"): d = d.lstrip("0")           # Spain has NO trunk prefix
    if len(d) != 9:
        return FAIL("TOO_SHORT" if len(d) < 9 else "TOO_LONG",
                    segment=failing_group_index(d, groups=(3, 2, 2, 2)))
    if not re.match(r"^(?:400|[5-9]\d\d)\d{6}$", d): return FAIL("RANGE", segment=0)
    kind = next(k for pat, k in ES_TYPE if re.match(pat, d))
    return OK("+34" + d, number_type=kind,
              speak_groups=(3, 3, 3) if kind == "toll_free" else (3, 2, 2, 2))

def validate_phone_intl(spoken, default_region):
    """Delegate to a libphonenumber-class library. NEVER hand-roll leading-zero
       rules: Spain has no trunk prefix, Italy keeps its leading zero, and '00'
       is an IDD only in regions whose IDD actually is 00."""
    text, ext = split_extension(spoken)   # ext/extension/extension/anexo/interno/x/#
    n = phonelib.parse(text, region=default_region)
    if not phonelib.is_possible(n):
        return FAIL(phonelib.possible_reason(n))      # TOO_SHORT|TOO_LONG|INVALID_LENGTH
    if not phonelib.is_valid(n): return FAIL("RANGE", segment=0)
    e164 = phonelib.format_e164(n)                    # '+' + CC + NSN, <= 15 digits
    assert len(re.sub(r"\D", "", e164)) <= 15         # ITU-T E.164 sec. 6.1
    return OK(phone=e164, extension=ext)              # two fields, NEVER concatenated

def can_sms(result):
    return result.number_type == "mobile"             # 70x is NOT a mobile

# --- 6. IBAN / CCC --------------------------------------------------------
def validate_iban(s):
    s = canon(s)
    if not re.match(r"^[A-Z]{2}\d{2}[A-Z0-9]{10,30}$", s): return FAIL("SHAPE")
    if s.startswith("ES") and len(s) != 24: return FAIL("LENGTH", expected=24)
    r = s[4:] + s[:4]
    n = int("".join(str(ord(c) - 55) if c.isalpha() else c for c in r))
    if n % 97 != 1: return FAIL("CHECKSUM", segment=failing_chunk_hint(s))
    if s.startswith("ES") and not _ccc_dc_ok(s): return FAIL("CCC_DC", segment="bank_or_account")
    return OK(s)
# ES9121000418450200051332 -> True; ES7921000813610123456789 -> True;
# GB82WEST12345698765432 -> True

def _ccc_dc_ok(iban_es):
    """Spanish national check digits (positions 15-16 of the IBAN).
       Localises a mod-97 failure to the bank/branch half or the account half."""
    bank, branch, dc, acct = iban_es[4:8], iban_es[8:12], iban_es[12:14], iban_es[14:24]
    w = [1, 2, 4, 8, 5, 10, 9, 7, 3, 6]
    def d(x):
        r = 11 - sum(int(c) * w[i] for i, c in enumerate(x)) % 11
        return {10: "1", 11: "0"}.get(r, str(r))
    return d("00" + bank + branch) + d(acct) == dc
# bank 2100, branch 0418, acct 0200051332 -> "45", matching ES91 2100 0418 45 ...

def ccc_to_iban(ccc20):
    """Caller read the legacy 20-digit CCC. Compute the IBAN check digits
       rather than asking for them - the caller does not know them."""
    body = ccc20 + "142800"                            # 'ES' -> 14 28, then '00'
    return "ES" + f"{98 - int(body) % 97:02d}" + ccc20

# --- 7. Card --------------------------------------------------------------
def capture_card(spoken):
    """The spoken channel captures LAST FOUR ONLY. A longer run is truncated in
       state and never written to a log, transcript field or tool argument.
       CVV/CVC, track data and PIN are never requested, echoed or stored."""
    d = re.sub(r"\D", "", expand_spoken_digits(spoken))
    if len(d) > 4: emit_event("FULL_PAN_HEARD_TRUNCATED")   # and interrupt the caller
    return OK(last4=d[-4:])

def luhn_ok(pan):                     # tool layer only, never the spoken channel
    t = 0
    for i, c in enumerate(reversed(pan)):
        x = int(c) * (2 if i % 2 else 1)
        t += x - 9 if x > 9 else x
    return t % 10 == 0
# 4111111111111111 True; 5555555555554444 True; 4111111111111112 False

def validate_expiry(mm, yy):
    return 1 <= int(mm) <= 12 and 0 <= (2000 + int(yy)) - today.year <= 10

# --- 8. Date of birth, postal code, email, codes --------------------------
def validate_dob(a, b, c, lang):
    """ONE explicit question when both leading components could be a month."""
    if int(a) <= 12 and int(b) <= 12 and a != b: return NEEDS_ORDER_QUESTION(a, b)
    day, month = (a, b) if lang == "es" else (b, a)
    year = int(c) if len(str(c)) == 4 else _century(int(c))
    if not date_exists(year, month, day): return FAIL("IMPOSSIBLE_DATE")
    if not 16 <= age(year, month, day) <= 110: return FAIL("IMPLAUSIBLE_AGE")
    return NEEDS_EXPLICIT_CONFIRMATION(iso(year, month, day))   # no checksum

def _century(yy):
    """62 -> 1962, not 2062: pick the century that yields a plausible age."""
    return 1900 + yy if age_of(2000 + yy) < 16 else 2000 + yy

def validate_postal_es(spoken, stated_locality=None):
    d = re.sub(r"\D", "", expand_spoken_digits(spoken, lang="es")).zfill(5)
    if len(d) != 5 or not 1 <= int(d[:2]) <= 52: return FAIL("SHAPE")
    if stated_locality and province_of(d[:2]) != province_of_locality(stated_locality):
        return FAIL("PROVINCE_MISMATCH", segment="postal_code")   # re-ask the CP, not the address
    return NEEDS_EXPLICIT_CONFIRMATION(d)

EMAIL_TOKENS = {"arroba": "@", "at": "@", "punto": ".", "dot": ".",
                "guion bajo": "_", "underscore": "_",
                "guion": "-", "dash": "-", "hyphen": "-"}

def validate_email(spoken):
    s = apply_tokens(spoken, EMAIL_TOKENS)
    s = ascii_fold(s.lower().replace(" ", ""))         # confirm the fold aloud once
    if s.count("@") != 1 or "." not in s.split("@")[1] or len(s) > 254:
        return FAIL("SHAPE")
    return NEEDS_EXPLICIT_CONFIRMATION(s, domain_shortlist_hit=known_provider(s))

def validate_code(spoken, template):
    """template comes from the TOOL CONTRACT (length, segments, separators, case).
       The agent never invents a checksum for a confirmation code."""
    s = re.sub(r"[^A-Z0-9]", "", canon(expand_repeats(spoken)))
    s = reinsert_separators(s, template)               # 'MBR-99021', not '99021'
    if not re.match(template.regex, s): return FAIL("SHAPE", segment=first_bad_chunk(s, template))
    return NEEDS_EXPLICIT_CONFIRMATION(s)              # chunks of 3-4, spelling alphabet

# --- 9. The gate every write tool passes through --------------------------
CHECKSUMMED = {"dni", "nie", "cif", "iban", "pan"}

def before_write_tool(call):
    for field, value in call.identifier_args():
        r = VALIDATORS[field.type](value)
        if not r.ok: return BLOCK(reason=r, repair=segment_reask(r))
        if field.type not in CHECKSUMMED and not r.explicitly_confirmed:
            return BLOCK(reason="NO_EXPLICIT_CONFIRMATION", repair=readback(field))
    return ALLOW(call)

# --- 10. Masking for anything the agent SPEAKS ----------------------------
MASK = {"dni": lambda v: f"...{v[5:8]}, letra {v[8]}",
        "nie": lambda v: f"...{v[5:8]}, letra {v[8]}",
        "passport": lambda v: f"...{v[-3:]}",
        "iban": lambda v: f"...{v[-4:]}",
        "pan": lambda v: f"...{v[-4:]}",
        "phone": lambda v: f"...{v[-3:]}",
        "email": lambda v: f"{v[0]}...@{v.split('@')[1]}"}

def speak(value, type_):
    return MASK[type_](value) if type_ in MASK else value   # tool args stay unmasked
